INSERT INTO lunar_sites (id, name, category, lat, lon, elevation_m, slope_deg, ice_probability_pct, annual_sunlight_pct, description) VALUES ('shackleton-rim', 'Borde del Cráter Shackleton', 'Polo Sur / Candidato Artemis', -89.9, 0.0, 4200.0, 14.5, 85.0, 86.2, 'Ubicado casi exactamente en el Polo Sur Lunar. Presenta picos con iluminación solar cuasi-permanente y un interior en sombra eterna (PSR) con ricas reservas de hielo de agua.');
INSERT INTO lunar_sites (id, name, category, lat, lon, elevation_m, slope_deg, ice_probability_pct, annual_sunlight_pct, description) VALUES ('malapert-massif', 'Montaña Malapert (Macizo)', 'Polo Sur / Relé de Comunicaciones', -85.99, 2.91, 5000.0, 9.2, 20.0, 89.4, 'Pico de luz casi eterna elevado a 5,000 metros. Mantiene una línea de visión directa continua con la Tierra, lo que lo convierte en el sitio ideal para la estación repetidora de telecomunicaciones de Artemis.');
INSERT INTO lunar_sites (id, name, category, lat, lon, elevation_m, slope_deg, ice_probability_pct, annual_sunlight_pct, description) VALUES ('connecting-ridge', 'Cresta de Conexión (Connecting Ridge)', 'Polo Sur / Corredor de Tránsito', -89.44, 222.0, 2100.0, 6.8, 45.0, 82.0, 'Cresta estratégica que conecta los cráteres Shackleton y de Gerlache. Proporciona condiciones excelentes de energía solar y rutas viables para rovers de superficie.');
INSERT INTO lunar_sites (id, name, category, lat, lon, elevation_m, slope_deg, ice_probability_pct, annual_sunlight_pct, description) VALUES ('faustini-rim', 'Borde del Cráter Faustini', 'Polo Sur / Recursos Volátiles', -87.3, 77.0, 1800.0, 18.0, 92.0, 74.5, 'Borde circumpolar sur con gradientes térmicos extremos. Entorno clave para estudiar la acumulación de volátiles lunares y la interacción con el regolito polar.');
INSERT INTO lunar_sites (id, name, category, lat, lon, elevation_m, slope_deg, ice_probability_pct, annual_sunlight_pct, description) VALUES ('apollo-11', 'Apolo 11 (Statio Tranquillitatis)', 'Histórico / Llanura Ecuatorial', 0.67408, 23.47297, -1200.0, 1.8, 0.0, 50.0, 'Primer alunizaje tripulado en la historia humana (20 de julio de 1969). Llanura basáltica del Mar de la Tranquilidad con ciclo diurno regular de 29.5 días terrestres y la Tierra siempre visible en el cielo.');
INSERT INTO lunar_sites (id, name, category, lat, lon, elevation_m, slope_deg, ice_probability_pct, annual_sunlight_pct, description) VALUES ('oceanus-procellarum', 'Océano de las Tormentas (Oceanus Procellarum)', 'Mar Lunar / Zona Occidental', 18.0, -64.0, -2000.0, 1.2, 0.0, 50.0, 'La mayor planicie lunar (mare) en la cara visible. Sitio histórico de sondas robóticas y referencia para comparar condiciones ecuatoriales/templadas de iluminación frente a los polos.');
